"""Build an offline review page from existing renders; no server or external assets."""
from pathlib import Path
import json,html
from PIL import Image,ImageDraw,ImageFont
ROOT=Path(__file__).resolve().parents[1]
m=json.loads((ROOT/'manifest/scene-manifest.json').read_text())
titles={
'CAM_WORLD_FULL':'完整屋顶 · 全园俯视','CAM_LAYOUT_TOP':'区域编号 · 顶视剖视','CAM_LAYOUT_AXON':'墙柱与家具 · 斜向剖视',
'CAM_ENTRY_SEATED':'01 临水廊下 · 默认坐姿','CAM_WATER_BRIDGE':'02 下桥 · 上游水园','CAM_ISLAND_SEATED':'03 低岛 · 圆垫坐姿','CAM_LIBRARY_SEATED':'04 阅读厅 · 临窗坐姿',
'CAM_COPY_VIEW':'05 抄经厅 · 案前观看','CAM_PRIVATE_SEATED':'06 独处侧室 · 坐姿','CAM_BELL_COURT':'07 钟庭 · 钟与石钵','CAM_WISH_APPROACH':'08 许愿树 · 到达','CAM_OLD_TREE_PATH':'09 景观大树 · 山径','CAM_LOOKOUT_N':'10 观景台 · 北向','CAM_CHAT_SEATED':'11 对话小屋 · 椅中','CAM_FRONT_GATE':'12 南门 · 共用前庭','CAM_LIBRARY_SHELF':'13 书架 · 选书近景',
'CAM_ISLAND_APPROACH':'低岛 · 站姿到达','CAM_ISLAND_SECTION':'低岛 · 岸桥剖面检查','CAM_LIBRARY_ENTRY':'阅读厅 · 门口站姿','CAM_COPY_RH':'抄写 · 右手构图','CAM_COPY_LH':'抄写 · 左手构图','CAM_COPY_ENTRY':'抄经厅 · 门口站姿','CAM_PRIVATE_ENTRY':'独处侧室 · 门口','CAM_WISH_READ':'许愿树 · 读签近景','CAM_LOOKOUT_E':'观景台 · 东向','CAM_LOOKOUT_W':'观景台 · 西北向','CAM_CHAT_ENTRY':'对话小屋 · 侧转入口','CAM_HELP_READ':'廊柱 · 帮助牌'}
refs={
'CAM_WORLD_FULL':'00-overview-courtyard-blossoms.png','CAM_ENTRY_SEATED':'01-waterside-veranda.png','CAM_WATER_BRIDGE':'02-water-garden-bridge.png','CAM_ISLAND_SEATED':'03-island-meditation.png','CAM_LIBRARY_SEATED':'04-library-seat.png','CAM_COPY_VIEW':'05-copy-hall-seated.png','CAM_PRIVATE_SEATED':'06-private-side-room.png','CAM_BELL_COURT':'07-bell-court.png','CAM_WISH_APPROACH':'08-wish-tree-platform.png','CAM_OLD_TREE_PATH':'09-old-tree-path.png','CAM_LOOKOUT_N':'10-right-lookout-dawn.png','CAM_CHAT_SEATED':'11-conversation-cottage-seat.png','CAM_FRONT_GATE':'12-front-court-threshold.png','CAM_LIBRARY_SHELF':'13-bookshelf-select.png'}
first=['CAM_WORLD_FULL','CAM_LAYOUT_TOP','CAM_ENTRY_SEATED','CAM_LIBRARY_SHELF']
main=['CAM_ENTRY_SEATED','CAM_WATER_BRIDGE','CAM_ISLAND_SEATED','CAM_LIBRARY_SEATED','CAM_COPY_VIEW','CAM_PRIVATE_SEATED','CAM_BELL_COURT','CAM_WISH_APPROACH','CAM_OLD_TREE_PATH','CAM_LOOKOUT_N','CAM_CHAT_SEATED','CAM_FRONT_GATE','CAM_LIBRARY_SHELF']
lookup={c['name']:c for c in m['cameras']}
items=[]
for name in first+main+[c['name'] for c in m['cameras']]:
 if any(x['name']==name for x in items):continue
 c=lookup[name];items.append({'name':name,'title':titles.get(name,name),'image':f'stills/{name}.png','reference':f'../../../style-studies-20261020/v8-first-person/{refs[name]}' if name in refs else None,'region':c['region'],'state':c['display_state'],'lens':c['lens_mm'],'ortho':c['ortho_m'],'group':'检查图' if name in first else '场所视点' if name in main else '结构补充'})
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Zenflow Space · 第一期灰模检查</title>
<style>*{box-sizing:border-box}body{margin:0;background:#eeeae1;color:#26372f;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}header{padding:24px 32px 20px;border-bottom:1px solid #ccd0c4;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{font-size:11px;letter-spacing:.19em;color:#687568}.title{font:400 27px Georgia,"Songti SC",serif;margin:7px 0}.sub{font-size:12px;color:#687568;line-height:1.7}.badge{display:inline-block;padding:7px 12px;border:1px solid #a8b4a1;border-radius:4px;font-size:12px;white-space:nowrap}main{display:grid;grid-template-columns:245px minmax(0,1fr);min-height:calc(100vh - 134px)}nav{padding:19px 14px;border-right:1px solid #ccd0c4;height:calc(100vh - 135px);overflow:auto}nav h3{font-size:10px;letter-spacing:.12em;color:#7c877b;margin:20px 10px 9px}nav h3:first-child{margin-top:0}nav button{background:transparent;border:0;width:100%;text-align:left;padding:11px 12px;margin:2px 0;color:#556151;border-radius:5px;cursor:pointer;font-size:12px;line-height:1.45}nav button:hover{background:#e1e3d7}nav button.active{background:#30493d;color:#f4f1e7}.review{padding:24px 30px;min-width:0}.bar{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:17px}h1{font:400 23px Georgia,"Songti SC",serif;margin:0}.controls{display:flex;gap:9px;align-items:center;font-size:12px}.controls button,a.button{font:inherit;color:#30493d;background:transparent;border:1px solid #aab5a4;padding:8px 12px;border-radius:4px;cursor:pointer;text-decoration:none}.frames{display:grid;grid-template-columns:minmax(0,1fr);gap:16px}.frames.compare{grid-template-columns:1fr 1fr}.frame{margin:0;min-width:0;background:#222b29;border-radius:5px;overflow:hidden}.frame img{width:100%;height:61vh;object-fit:contain;display:block}.frame figcaption{padding:10px 14px;color:#c5cdc4;font-size:11px;border-top:1px solid #3c4540;display:flex;justify-content:space-between}.reference{display:none}.compare .reference{display:block}.notes{font-size:12px;color:#687568;line-height:1.9;margin-top:17px;max-width:900px}.line{height:1px;background:#ccd0c4;margin:19px 0}.foot{display:flex;flex-wrap:wrap;gap:16px;font-size:12px}.foot a{color:#536c59;text-underline-offset:3px}.sr{font-size:10px;color:#7f897d;margin-top:10px}@media(max-width:1000px){.frames.compare{grid-template-columns:1fr}.frame img{height:53vh}header{padding:18px}.review{padding:18px}main{grid-template-columns:205px minmax(0,1fr)}}@media(max-width:650px){main{display:block}nav{height:auto;max-height:180px;border-right:0;border-bottom:1px solid #ccd0c4;display:flex;overflow:auto;gap:5px}nav h3{display:none}nav button{min-width:150px;width:150px}.bar{align-items:flex-start;flex-direction:column;gap:12px}.title{font-size:23px}.frame img{height:48vh}header{align-items:flex-start}.badge{display:none}.controls{flex-wrap:wrap}}</style>
<header><div><div class="brand">ZENFLOW SPACE / SPATIAL STUDY</div><div class="title">同一个庭院，28 个真实视点</div><div class="sub">第一期 · 全园灰模与空间检查　/　__VERSION__　/　2026.10.20</div></div><span class="badge">模型检查稿 · 待视觉评审</span></header><main><nav id="nav" aria-label="检查视点"></nav><section class="review"><div class="bar"><h1 id="heading"></h1><div class="controls"><button id="previous" aria-label="上一张">←</button><button id="next" aria-label="下一张">→</button><button id="compare" aria-pressed="false">对照定稿参考</button><a class="button" href="../zen-space.blend" download>Blender 源文件</a></div></div><div class="frames" id="frames"><figure class="frame"><img id="model" alt="当前灰模检查图"><figcaption><span>实际 Blender 模型</span><span id="state"></span></figcaption></figure><figure class="frame reference"><img id="reference" alt="对应的定稿概念参考图"><figcaption><span>定稿概念参考</span><span>视觉方向 / 不是测绘图</span></figcaption></figure></div><div class="notes">完整屋顶、剖视与第一视角来自同一主模型。灰色树冠、岸石、远山和灯具用于尺度与遮挡检查；最终木石、水面、暖暗灯光和日夜状态在后续阶段制作。参考图之间的透视差异，以实际邻接和可达性处理。</div><div class="line"></div><div class="foot"><a href="../README.md">打开与编辑说明</a><a href="../evidence/phase1-review.md">第一期校验记录</a><a href="../manifest/layout-register.csv">区域尺寸</a><a href="../manifest/camera-register.csv">镜头参数</a><a href="../evidence/reference-analysis.md">参考图差异</a></div><div class="sr">方向键切换；C 键对照参考。所有文件本地读取，页面不发送内容。</div></section></main>
<script>const items=__DATA__;let current=0,comparison=false;const nav=document.getElementById('nav');let last='';items.forEach((v,i)=>{if(v.group!==last){const h=document.createElement('h3');h.textContent=v.group;nav.appendChild(h);last=v.group}const b=document.createElement('button');b.textContent=v.title;b.onclick=()=>show(i);b.dataset.index=i;nav.appendChild(b)});function show(i){current=(i+items.length)%items.length;const v=items[current];document.getElementById('heading').textContent=v.title;document.getElementById('model').src=v.image;document.getElementById('reference').src=v.reference||'';document.getElementById('state').textContent=v.state==='LAYOUT_CUTAWAY'?'指定屋面剖视':'保留完整屋顶与遮挡';document.querySelectorAll('nav button').forEach((b,j)=>b.classList.toggle('active',j===current));document.getElementById('compare').disabled=!v.reference;document.getElementById('compare').style.opacity=v.reference?'1':'.4';document.getElementById('frames').classList.toggle('compare',comparison&&!!v.reference)}document.getElementById('previous').onclick=()=>show(current-1);document.getElementById('next').onclick=()=>show(current+1);document.getElementById('compare').onclick=()=>{comparison=!comparison;document.getElementById('compare').setAttribute('aria-pressed',comparison);show(current)};window.addEventListener('keydown',e=>{if(e.key==='ArrowRight')show(current+1);if(e.key==='ArrowLeft')show(current-1);if(e.key.toLowerCase()==='c')document.getElementById('compare').click()});show(0);</script></html>'''
page=page.replace('__DATA__',json.dumps(items,ensure_ascii=False)).replace('__VERSION__',m['version'])
(ROOT/'previews/index.html').write_text(page)
# Compact four-image checkpoint with legible captions, using an available local Chinese font.
font=ImageFont.truetype('/System/Library/Fonts/Hiragino Sans GB.ttc',24)
canvas=Image.new('RGB',(1640,1120),'#eeeae1');d=ImageDraw.Draw(canvas)
for i,name in enumerate(first):
 im=Image.open(ROOT/'previews/stills'/f'{name}.png').convert('RGB');im.thumbnail((800,500));x=20+(i%2)*820;y=20+(i//2)*550
 canvas.paste(im,(x,y+35));d.text((x+4,y),titles[name],font=font,fill='#26372f')
canvas.save(ROOT/'previews/phase1-four-checks.jpg',quality=93)
# All 13 first-person review stations on two contact sheets, originals remain full size.
for k in range(2):
 batch=main[k*7:(k+1)*7];sh=Image.new('RGB',(1600,((len(batch)+1)//2)*530),'#eeeae1');draw=ImageDraw.Draw(sh)
 for i,name in enumerate(batch):
  im=Image.open(ROOT/'previews/stills'/f'{name}.png').convert('RGB');im.thumbnail((790,494));xx=(i%2)*800;yy=(i//2)*530
  sh.paste(im,(xx,yy+30));draw.text((xx+8,yy+2),titles[name],font=font,fill='#26372f')
 sh.save(ROOT/f'previews/phase1-views-{k+1}.jpg',quality=93)
print('Gallery and review sheets created:',len(items),'views')
